module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] current_state, next_state;

    // State encoding
    localparam STATE0 = 2'b00,
               STATE1 = 2'b01,
               STATE2 = 2'b10;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= STATE0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            STATE0: next_state = STATE1;
            STATE1: next_state = STATE2;
            STATE2: next_state = STATE0;
            default: next_state = STATE0;
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output reg [2:0] light
);

    // State encoding
    localparam GREEN  = 3'b100;
    localparam YELLOW = 3'b010;
    localparam RED    = 3'b001;

    reg [1:0] state;
    reg [3:0] counter;

    // State transition and counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= GREEN;
            counter <= 0;
            light <= GREEN;
        end else begin
            case (state)
                GREEN: begin
                    if (counter == 4'd9) begin
                        state <= YELLOW;
                        counter <= 0;
                    end else begin
                        counter <= counter + 1;
                    end
                    light <= GREEN;
                end

                YELLOW: begin
                    if (counter == 4'd2) begin
                        state <= RED;
                        counter <= 0;
                    end else begin
                        counter <= counter + 1;
                    end
                    light <= YELLOW;
                end

                RED: begin
                    if (counter == 4'd9) begin
                        state <= GREEN;
                        counter <= 0;
                    end else begin
                        counter <= counter + 1;
                    end
                    light <= RED;
                end

                default: begin
                    state <= GREEN;
                    counter <= 0;
                    light <= GREEN;
                end
            endcase
        end
    end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [1:0] current_state, next_state;

    // State encoding
    parameter IDLE  = 2'b00;
    parameter UP    = 2'b01;
    parameter DOWN  = 2'b10;
    parameter WAIT  = 2'b11;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (up_request) 
                    next_state = UP;
                else if (down_request) 
                    next_state = DOWN;
                else 
                    next_state = IDLE;
            end

            UP: begin
                if (!up_request) 
                    next_state = WAIT;
                else 
                    next_state = UP;
            end

            DOWN: begin
                if (!down_request) 
                    next_state = WAIT;
                else 
                    next_state = DOWN;
            end

            WAIT: begin
                if (up_request) 
                    next_state = UP;
                else if (down_request) 
                    next_state = DOWN;
                else 
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output reg [1:0] state
);

// 状态定义
localparam IDLE = 2'b00;
localparam COIN_ACCEPTED = 2'b01;
localparam DISPENSING = 2'b10;

// 状态转移逻辑
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (coin_inserted) begin
                    state <= COIN_ACCEPTED;
                end else begin
                    state <= IDLE;
                end
            end

            COIN_ACCEPTED: begin
                if (item_selected) begin
                    state <= DISPENSING;
                end else if (coin_inserted) begin
                    // 继续接受投币，保持当前状态
                    state <= COIN_ACCEPTED;
                end else begin
                    state <= COIN_ACCEPTED;
                end
            end

            DISPENSING: begin
                // 出货后返回空闲状态
                state <= IDLE;
            end

            default: begin
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    reg signed [15:0] result;
    integer i;

    always @(*) begin
        result = 16'sd1;
        if (in_1 >= 0) begin
            for (i = 0; i < in_1; i = i + 1) begin
                result = result * in_0;
            end
        end else begin
            result = 16'sd0;
        end
    end

    assign out = result;
endmodule

module log2_int (
