    out_reg = 0;
    found = 0;
    if (in_0 > 0) begin
        for (integer i = 15; i >= 0; i = i - 1) begin
            if (!found && in_0[i]) begin
                out_reg = i;
                found = 1;
            end
        end
    end
end

assign out = out_reg;

