module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
    reg [7:0] bin_count;
    wire [7:0] gray_next;
    wire [7:0] bin_next;

    // Binary to Gray conversion
    assign gray_next = bin_next ^ (bin_next >> 1);

    // Next binary value (simple increment)
    assign bin_next = bin_count + 1'b1;

    // Sequential logic for binary counter
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            bin_count <= 8'b0;
        end else begin
            bin_count <= bin_next;
        end
    end

    // Continuous assignment for Gray code output
    assign count = gray_next;

endmodule

