module TopModule (
  input clk,
  input in,
  input reset,
  output out
);

  // State encoding
  localparam [1:0] S0 = 2'b00,
                   S1 = 2'b01,
                   S2 = 2'b10;

  reg [1:0] state, next_state;

  // State register
  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? S2 : S0;
      S2: next_state = in ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic (Moore type)
  assign out = (state == S2);

endmodule

