    assign A_greater = (A > B);
    assign A_less = (A < B);

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_r;
reg a_rr;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_r <= 1'b0;
		a_rr <= 1'b0;
	end else begin
		a_r <= a;
		a_rr <= a_r;
	end
end

always @(*) begin
	rise = a_r & ~a_rr;
	down = ~a_r & a_rr;
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [31:0] count;
    wire [31:0] half_div;

    assign half_div = NUM_DIV / 2 - 1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 0;
            clk_div <= 1'b0;
        end
        else begin
            if (count == half_div) begin
                count <= 0;
                clk_div <= ~clk_div;
            end
            else begin
                count <= count + 1;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output reg [2:0] ins,
    output reg [4:0] ad1,
    output reg [7:0] ad2
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        ins <= 3'b000;
        ad1 <= 5'b00000;
        ad2 <= 8'b00000000;
    end
    else if (fetch != 2'b00) begin
        ins <= data[7:5];
        ad1 <= data[4:0];
        ad2 <= data;
    end
end

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      out <= 4'b0001;
    end else begin
      out[3:1] <= out[2:0];
      out[0] <= out[3] ^ out[2];
    end
  end
endmodule

module right_shifter(clk, q, d);
    input clk;
    input d;
    output reg [7:0] q;

    always @(posedge clk) begin
        q <= {d, q[7:1]};
    end
endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    reg [3:0] data_latch;
    reg toggle_a;

    reg toggle_sync1;
    reg toggle_sync2;
    reg toggle_sync2_d;

    // Clock domain A: latch data and toggle
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_latch <= 4'b0;
            toggle_a <= 1'b0;
        end else if (data_en) begin
            data_latch <= data_in;
            toggle_a <= ~toggle_a;
        end
    end

    // Clock domain B: double-sync toggle signal
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            toggle_sync1 <= 1'b0;
            toggle_sync2 <= 1'b0;
            toggle_sync2_d <= 1'b0;
        end else begin
            toggle_sync1 <= toggle_a;
            toggle_sync2 <= toggle_sync1;
            toggle_sync2_d <= toggle_sync2;
        end
    end

    // Clock domain B: capture data on toggle edge
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            dataout <= 4'b0;
        end else if (toggle_sync2 != toggle_sync2_d) begin
            dataout <= data_latch;
        end
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// State encoding
parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

reg [2:0] current_state, next_state;

// State register
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S2 : S0;
        S2: next_state = IN ? S2 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S2 : S0;
        default: next_state = S0;
    endcase
end

// Output logic
always @(*) begin
    case (current_state)
        S4: MATCH = 1'b1;
        default: MATCH = 1'b0;
    endcase
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [1:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'd0;
            valid_out <= 1'b0;
            dout <= 1'b0;
        end else begin
            if (cnt == 2'd3) begin
                cnt <= 2'd0;
            end else begin
                cnt <= cnt + 1'b1;
            end

            if (cnt < 2'd4) begin
                valid_out <= 1'b1;
                dout <= d[cnt];
            end else begin
                valid_out <= 1'b0;
                dout <= 1'b0;
            end
        end
    end

endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

    // Declare memory array
    reg [15:0] memory [0:255];

    // Initialize memory with example data (all zeros as default)
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            memory[i] = 16'h0000;
        end
        // Optionally preload specific addresses
        memory[8'h00] = 16'h1234;
        memory[8'h01] = 16'h5678;
        memory[8'h02] = 16'h9ABC;
        memory[8'h03] = 16'hDEF0;
    end

    // Asynchronous read
    always @(*) begin
        dout = memory[addr];
    end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output reg sequence_detected				
     );

    // 状态定义
    parameter S_IDLE  = 3'b000;
    parameter S_1     = 3'b001; // 检测到第一个1
    parameter S_11    = 3'b010; // 检测到"11"
    parameter S_110   = 3'b011; // 检测到"110"
    parameter S_1101  = 3'b100; // 检测到"1101"，输出有效

    reg [2:0] current_state, next_state;

    // 状态寄存器更新
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= S_IDLE;
        else
            current_state <= next_state;
    end

    // 下一状态逻辑（组合逻辑）
    always @(*) begin
        case (current_state)
            S_IDLE: begin
                if (data_in == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end

            S_1: begin
                if (data_in == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE; // 序列中断，回到初始状态
            end

            S_11: begin
                if (data_in == 1'b0)
                    next_state = S_110;
                else // data_in == 1'b1
                    next_state = S_11; // 保持在S_11，因为"111"的前两个"11"仍有效
            end

            S_110: begin
                if (data_in == 1'b1)
                    next_state = S_1101;
                else
                    next_state = S_IDLE; // 序列中断，回到初始状态
            end

            S_1101: begin // 一个序列已检测完成
                // 检查重叠序列的可能性："1101101"，最后两个"01"可以作为新序列的开始
                if (data_in == 1'b1)
                    next_state = S_1; // 检测到一个新的1，开始可能的"1101"
                else
                    next_state = S_IDLE;
            end

            default: next_state = S_IDLE;
        endcase
    end

    // 输出逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            sequence_detected <= 1'b0;
        else if (current_state == S_1101)
            sequence_detected <= 1'b1;
        else
            sequence_detected <= 1'b0;
    end

endmodule
